import {RECREATION,recreationActive} from './recreation.js?v=public-space-garbage-1';
// Prima table 14-2, pp.216–217: garbage weights / 100, per building/month.
export const RECREATION_WASTE={largePark:.9,pond:.4,playground:.4,marina:3.6,zoo:6.4,sportsPark:3.2};
export const TRANSIT_WASTE={busStop:.4,trainStation:2.4,subwayStation:.6,railTransfer:.6};
const names={busStop:'Bus stop',trainStation:'Train station',subwayStation:'Subway station',railTransfer:'Rail–subway connection'};
export function publicSpaceWasteProduction(c,t){if(RECREATION_WASTE[t.type])return t.root===t.y*c.size+t.x&&recreationActive(c,t)?RECREATION_WASTE[t.type]:0;if(!TRANSIT_WASTE[t.type]||t.fire||t.rubble||t.radiation||c.transport.funding<=0||c.transport.condition<=20||c.transport.underfunded>=6)return 0;return (t.type==='busStop'?t.stopActive:t.stationActive)?TRANSIT_WASTE[t.type]:0;}
function rootFor(c,t){return RECREATION[t.type]&&Number.isInteger(t.root)?c.tiles[t.root]:t;}
function waiting(c,t){if(!RECREATION[t.type])return t.waste||0;let total=0;for(let y=t.y;y<t.y+RECREATION[t.type].size;y++)for(let x=t.x;x<t.x+RECREATION[t.type].size;x++){const u=c.tiles[y*c.size+x];if(u?.root===t.root)total+=u.waste||0;}return total;}
export function publicSpaceWasteSources(c){return c.tiles.filter(t=>TRANSIT_WASTE[t.type]||RECREATION_WASTE[t.type]&&t.root===t.y*c.size+t.x).map(t=>({type:t.type,name:RECREATION[t.type]?.name||names[t.type],rate:publicSpaceWasteProduction(c,t),waiting:waiting(c,t)}));}
export function publicSpaceGarbageInspection(c,t){if(!TRANSIT_WASTE[t.type]&&!RECREATION_WASTE[t.type])return '';t=rootFor(c,t);return `<p>Garbage: ${publicSpaceWasteProduction(c,t).toFixed(2)} units/month · ${waiting(c,t).toFixed(2)} waiting. Connect a nearby road to disposal capacity or a garbage-export route. Recreation uses access beside its whole footprint; a rail or subway passenger connection alone does not provide road collection.</p>`;}
export function publicSpaceWasteReport(c){const sources=publicSpaceWasteSources(c);if(!sources.length)return '';const groups=new Map(),fmt=n=>n.toLocaleString('en-US',{maximumFractionDigits:2});for(const s of sources){const g=groups.get(s.type)||{name:s.name,count:0,rate:0,waiting:0};g.count++;g.rate+=s.rate;g.waiting+=s.waiting;groups.set(s.type,g);}return `<details><summary>Recreation and transit · garbage</summary><p>These sites add ${fmt(sources.reduce((sum,s)=>sum+s.rate,0))} units/month to city garbage, included in total production.</p><div class="table-scroll"><table aria-label="Public space garbage"><thead><tr><th>Site</th><th>Buildings</th><th>Units/month</th><th>Waiting</th></tr></thead><tbody>${[...groups.values()].map(g=>`<tr><th scope="row">${g.name}</th><td>${g.count}</td><td>${fmt(g.rate)}</td><td>${fmt(g.waiting)}</td></tr>`).join('')}</tbody></table></div><p>Inspect a site for its backlog. Open recreation can produce waste without a road; collection needs a usable route. Transit waste follows stop/station operation. Damage or a transit shutdown stops new production, but existing garbage remains.</p></details>`;}
